import re
from datetime import datetime

_DISPLAY_NAME_RE = re.compile(r"<([^<>]*)>")
_PHONE_EXT_RE = re.compile(r"ext|x|#", re.IGNORECASE)
_ZIP_PLUS4_RE = re.compile(r"[0-9]{5}-[0-9]{4}")
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}


def _is_digits(s, length):
    return len(s) == length and all(c in "0123456789" for c in s)


def _norm_email(raw):
    s = raw.strip()
    m = _DISPLAY_NAME_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.replace(".", "").split("+", 1)[0]
            s = local + "@gmail.com"
    return s


def _valid_email(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _norm_phone(raw):
    m = _PHONE_EXT_RE.search(raw)
    s = raw[:m.start()] if m else raw
    digits = "".join(c for c in s if c in "0123456789")
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _valid_phone(digits):
    return _is_digits(digits, 10) and digits[0] not in "01"


def _norm_zip(raw):
    s = raw.strip()
    if _ZIP_PLUS4_RE.fullmatch(s):
        s = s.split("-")[0]
    if _is_digits(s, 4):
        s = "0" + s
    return s if _is_digits(s, 5) else ""


def _norm_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        return s.title()
    return s


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _norm_tags(raw):
    tags = {t.strip().lower() for t in re.split(r"[;,]", raw)}
    tags.discard("")
    return tags


def _pick(group, field):
    """Choose the group's value for a field: manual rows first,
    then most recent 'updated', then earliest input row."""
    cands = [r for r in group if r[field]]  # group is in input order
    if not cands:
        return ""
    # Newest first; sorted() with reverse=True keeps input order for ties.
    ranked = sorted(cands, key=lambda r: r["updated"], reverse=True)
    # Stable sort: manual rows (key False) move ahead, keeping the order above.
    ranked.sort(key=lambda r: r["source"] != "manual")
    return ranked[0][field]


def _summarize(group):
    tags = set()
    for r in group:
        tags |= r["tags"]
    return {
        "first_name": _pick(group, "first"),
        "last_name": _pick(group, "last"),
        "zip": _pick(group, "zip"),
        "email": _pick(group, "email"),
        "phone": _pick(group, "phone"),
        "source": _pick(group, "source"),
        "tags": ";".join(sorted(tags)),
        "opted_out": "Y" if any(r["opted_out"] for r in group) else "N",
        "updated": max(r["updated"] for r in group).strftime("%Y-%m-%d"),
    }


def dedupe_contacts(rows):
    # Normalize each row; drop rows with neither a valid email nor a valid phone.
    recs = []
    for row in rows:
        email = _norm_email(row.get("email", ""))
        if not _valid_email(email):
            email = ""
        phone = _norm_phone(row.get("phone", ""))
        if not _valid_phone(phone):
            phone = ""
        if not email and not phone:
            continue
        recs.append({
            "first": _norm_name(row.get("first_name", "")),
            "last": _norm_name(row.get("last_name", "")),
            "zip": _norm_zip(row.get("zip", "")),
            "email": email,
            "phone": phone,
            "source": row.get("source", "").strip().lower(),
            "tags": _norm_tags(row.get("tags", "")),
            "opted_out": row.get("opted_out", "").strip().lower() in _OPT_OUT_VALUES,
            "updated": _parse_updated(row["updated"]),
        })

    # Union-find over row indexes: rows sharing a valid email, or a valid
    # phone plus the same non-empty last name, are the same person.
    parent = list(range(len(recs)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)

    first_by_email = {}
    first_by_phone_last = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in first_by_email:
                union(first_by_email[r["email"]], i)
            else:
                first_by_email[r["email"]] = i
        if r["phone"] and r["last"]:
            key = (r["phone"], r["last"].casefold())
            if key in first_by_phone_last:
                union(first_by_phone_last[key], i)
            else:
                first_by_phone_last[key] = i

    # Group rows; dict insertion order gives people in order of earliest row.
    groups = {}
    for i, r in enumerate(recs):
        groups.setdefault(find(i), []).append(r)

    return [_summarize(group) for group in groups.values()]
